SELECT name FROM employees
WHERE salary > ALL (
  SELECT salary FROM employees WHERE dept_id = 10
);

SELECT c.id,
  (SELECT COUNT(*) FROM orders o WHERE o.customer_id = c.id) AS n
FROM customers c;

SELECT AVG(cnt)
FROM (
  SELECT customer_id, COUNT(*) AS cnt
  FROM orders
  GROUP BY customer_id
) t;

